import json,html
from pathlib import Path
ROOT=Path(__file__).parent
E=lambda s:html.escape(str(s),quote=True)
def section(private=False):
    a=json.loads((ROOT/'military-audit.json').read_text('utf8'))
    keys=['stavropol_88']+(['marshalkin_spellings_547'] if private else [])
    records=[{k:r[k] for k in ('no','fio','birth','rank','award','url')} for r in a['records'] if r['in_stavropol_selection'] or (private and r['marshalkin_family_spelling'])]
    data=json.dumps(dict(scopes={k:a['scopes'][k] for k in keys},records=records),ensure_ascii=False).replace('</','<\\/')
    options='<option value="stavropol_88">Ставрополье · 88 записей</option>'+('<option value="marshalkin_spellings_547">Все написания Маршалкин · 547 записей</option>' if private else '')
    return '''<style>.service-atlas,.life-atlas{max-width:1100px;margin:60px auto;padding:24px;color:#42301f}.service-atlas h2,.life-atlas h2{font-size:clamp(32px,4vw,52px)}.service-atlas select{font:inherit;max-width:100%;padding:12px;background:#f7eedc;border:1px solid #ac8853}.service-metrics,.service-highlights,.life-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin:24px 0}.service-metrics>div,.service-highlights>article,.life-grid>article{padding:22px;background:#eee1c9;border:1px solid #c9aa77}.service-metrics strong{display:block;font:52px var(--serif,Georgia)}.service-columns{display:grid;grid-template-columns:1fr 1fr;gap:30px}.service-bar{display:block;position:relative;width:100%;text-align:left;background:transparent;border:0;border-bottom:1px solid #cbb99b;padding:10px 8px 14px;cursor:pointer;color:inherit;font:inherit}.service-bar span{display:flex;justify-content:space-between;gap:15px}.service-bar i{position:absolute;left:0;bottom:0;height:3px;background:#a67b37}.service-evidence{max-height:400px;overflow:auto;border:1px solid #c9aa77;padding:18px}.service-evidence:empty{display:none}.service-evidence li{margin:12px 0}.service-atlas small,.life-atlas small{display:block;color:#775a38}.service-symbol{width:46px;height:46px;stroke:#9c7034;fill:none;stroke-width:1.5}.life-grid h3{font-size:29px;line-height:1.12}.life-grid button{margin-top:12px;cursor:pointer}.service-atlas details{margin:18px 0}.service-atlas summary{cursor:pointer}.life-grid p{font-size:15px}.life-atlas .life-status{font:600 11px var(--sans);letter-spacing:.08em;text-transform:uppercase}@media(max-width:700px){.service-columns,.life-grid{grid-template-columns:1fr}.service-metrics{gap:6px}.service-metrics>div{padding:10px;font-size:12px}.service-highlights{grid-template-columns:1fr}.service-atlas,.life-atlas{padding:18px}.service-metrics strong{font-size:38px}}</style><section class="service-atlas" id="military-stats"><small>ВОЕННАЯ СЛУЖБА · ЗВАНИЯ И НАГРАДЫ</small><h2>Воинские звания и награды</h2><p>Какие звания и награды сохранила выгрузка «Памяти народа». Здесь считаются записи документов, а не уникальные люди: один военнослужащий может встречаться несколько раз.</p><label>Охват анализа <select id="service-scope">'''+options+'''</select></label><div class="service-metrics" id="service-metrics"></div><div class="service-highlights"><article><svg class="service-symbol" viewBox="0 0 48 48" aria-hidden="true"><path d="M10 4h28l-7 16H17zM24 23l4 7 8 1-6 6 1 8-7-4-7 4 1-8-6-6 8-1z"/></svg><h3>«За отвагу»</h3><p>7 записей в ставропольской подборке; 25 — среди всех 547 записей Маршалкиных. Откройте строку диаграммы, чтобы увидеть имена.</p></article><article><svg class="service-symbol" viewBox="0 0 48 48" aria-hidden="true"><path d="M24 3l6 14 15 2-11 11 3 15-13-7-13 7 3-15L3 19l15-2z"/></svg><h3>Орден Славы III степени</h3><p>Одна ставропольская запись — №205. Орден Красной Звезды указан в двух строках: №163 и №679.</p><small>Пиктограммы условные, не изображения наград.</small></article><article><svg class="service-symbol" viewBox="0 0 48 48" aria-hidden="true"><path d="M9 43V9l15-6 15 6v34zM16 17l8-5 8 5M16 26l8-5 8 5M16 35l8-5 8 5"/></svg><h3>Офицерские судьбы</h3><p>Капитан Пётр Афанасьевич, 1919 года рождения, №410 — наивысшее явно указанное звание в подборке 88 записей.</p><small>Это не предел званий всего рода.</small></article></div><div class="service-columns"><div><h3>Воинские звания</h3><div id="service-ranks"></div></div><div><h3>Награды в документах</h3><div id="service-awards"></div></div></div><p>Нажмите на строку диаграммы — ниже появятся документы и имена.</p><div id="service-evidence" class="service-evidence" aria-live="polite"></div><p id="service-missing"></p><details><summary>Охват, пропуски и границы выводов</summary><p>В Excel 737 строк: 547 относятся к написаниям Маршалкин/Моршалкин и их вариантам, 190 — к Маршанским/Моршанским. Географический отбор не доказывает родство. Пустое поле не означает отсутствия награды или звания. Обозначение гвардейской части отделено от звания; сокращения раскрыты, различия родов службы сохранены. Если в строке несколько званий, она учитывается в нескольких категориях.</p><p>Есть послевоенные и юбилейные документы: без даты награждения нельзя относить все награды к 1941–1945 годам. Записей о звании Героя СССР/России или «Золотой Звезде» в этой выгрузке не найдено; это не утверждение обо всех членах рода.</p>'''+('''<p>В расширенной выборке встречаются полковники Борис Исаевич, Борис Фёдорович и Олег Сергеевич; у Бориса Исаевича — орден Красного Знамени (№76). Их связь с семейным древом не установлена. Смените охват и откройте соответствующие строки диаграмм.</p><p>Отдельный кандидат на сверку: Павел Михайлович, 29.10.1921, №399 и №400. Полные даты совпадают, но в одной записи указан майор административной службы без места рождения, в другой — старший лейтенант медицинской службы со ставропольским местом рождения. Объединять их без проверки документов нельзя.</p>''' if private else '')+'''</details></section><script>(()=>{const data=DATA,root=document.querySelector('#military-stats'),sel=root.querySelector('#service-scope');const el=(tag,text)=>{let n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n};function show(row){const box=root.querySelector('#service-evidence');box.replaceChildren(el('h3',row.label+' · '+row.count+' записей'));const ul=el('ul');for(const id of row.record_ids){const r=data.records.find(r=>r.no===id);if(!r)continue;const li=el('li'),a=el('a',r.fio+' · '+r.birth+' · №'+id);a.href=r.url;a.target='_blank';a.rel='noopener';li.append(a,el('small',[r.rank,r.award].filter(Boolean).join(' · ')));ul.append(li)}box.append(ul);box.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}function draw(){const s=data.scopes[sel.value];root.querySelector('#service-metrics').innerHTML=`<div><strong>${s.total_records}</strong>записей в выборке</div><div><strong>${s.records_with_recognized_rank}</strong>с распознанным званием</div><div><strong>${s.award_field_nonempty}</strong>с указанной наградой · ${s.award_types} видов</div>`;for(const [key,id] of [['ranks','service-ranks'],['awards','service-awards']]){const host=root.querySelector('#'+id);host.replaceChildren();const max=Math.max(...s[key].map(r=>r.count));for(const row of s[key]){const b=el('button'),span=el('span'),bar=el('i');b.className='service-bar';span.append(el('span',row.label),el('b',row.count));bar.style.width=(100*row.count/max)+'%';b.append(span,bar);b.onclick=()=>show(row);host.append(b)}}root.querySelector('#service-evidence').replaceChildren();root.querySelector('#service-missing').textContent=`Пробелы источника: ${s.rank_field_empty} пустых полей звания; ${s.status_or_occupation_only} содержат статус или занятие вместо звания. В ${s.award_field_empty} строках награда не указана. Гвардейское обозначение есть в ${s.guard_record_count} строках.`}sel.onchange=draw;draw()})();</script>'''.replace('DATA',data)

def biographies():
    a=json.loads((ROOT/'biographies-audit.json').read_text('utf8'))
    cards=[]
    icons=['M12 39l10-15 11 14M22 24l-9-9M22 24l14-12M23 13a5 5 0 1 0 0-10a5 5 0 0 0 0 10','M18 3v16L7 39q-2 6 5 6h24q7 0 5-6L30 19V3M15 3h18M14 31h20','M19 4h10v14h14v10H29v14H19V28H5V18h14z']
    for c,icon in zip(a['candidates'],icons):
        family=c['status']=='family_source_only'
        status='Сопоставлено по семейной записи Familio' if c['familyId']=='full-T204' else 'Семейное свидетельство' if family else 'Находка для проверки · родство не подтверждено'
        facts=''.join('<p>'+E(f)+'</p>' for f in c['facts'])
        urls=c['sourceUrls'][:1 if family else 2]
        links=' · '.join(f'<a href="{E(u)}" target="_blank" rel="noopener">Источник {i+1} ↗</a>' for i,u in enumerate(urls))
        caution='Театр, роли и награды в открытых источниках не установлены.' if family else ('Запись Дениса в Familio с датой 20.11.1942 прямо указывает докторскую степень и ссылается на эту биографию. Сопоставление поддержано семейным исследованием; смерть отмечена приблизительно около 2022 года.' if c['familyId']=='full-T204' else 'Совпадают имя, отчество и 1970 год рождения. Семейная карточка V205 не содержит полной даты и профессии, поэтому тождество пока не доказано. Должности приведены по публикациям, а не как актуальные.')
        cards.append(f'<article><svg class="service-symbol" viewBox="0 0 48 48" aria-hidden="true"><path d="{icon}"/></svg><small>{E(c["category"])}</small><h3>{E(c["name"])}</h3><p class="life-status">{status}</p>{facts}<p>{caution}</p>{links}<br><button onclick="window.focusPerson(\'{c["familyId"]}\')">Сопоставить с карточкой дерева ↗</button></article>')
    return '<section id="lives" class="life-atlas"><small>ЛЮДИ И ПРИЗВАНИЯ</small><h2>Биографии родственников</h2><p>Балет, химическая наука, медицина. Семейные свидетельства и открытые биографии сопоставлены отдельно: совпадение имени не делает однофамильца родственником.</p><div class="life-grid">'+''.join(cards)+'</div><details><summary>Что проверено и что ещё предстоит</summary><p>Проверены 903 извлечённые карточки, доступная таблица контактов и сохранённые семейные комментарии. Полные комментарии исходной схемы, XMind и хронологии в локальных материалах представлены не полностью. Поэтому это начало биографического исследования, а не исчерпывающий список профессий семьи. Для биографии Семёна требуется подтверждение тождества. Михаил сопоставлен по семейной записи Familio, содержащей ссылку на биографию РАЕ.</p></details></section>'
